from __future__ import annotations
import numpy as np

def seidel_matrix(adjacency: np.ndarray) -> np.ndarray:
    """Seidel matrix S = J - I - 2A of a simple graph."""
    n = adjacency.shape[0]
    return np.ones((n, n)) - np.eye(n) - 2.0 * adjacency.astype(float)

def seidel_energy(adjacency: np.ndarray) -> float:
    """Seidel energy E_S(G) = sum_i |lambda_i|."""
    return float(np.sum(np.abs(np.linalg.eigvalsh(seidel_matrix(adjacency)))))

def moments(adjacency: np.ndarray) -> tuple[float, float]:
    """Return (tr S, tr S^2): the first and second spectral moments."""
    s = seidel_matrix(adjacency)
    return float(np.trace(s)), float(np.trace(s @ s))

if __name__ == "__main__":
    rng = np.random.default_rng(0)
    for n in (5, 8, 12):
        upper = np.triu(rng.integers(0, 2, size=(n, n)), k=1)
        adj = upper + upper.T
        m1, m2 = moments(adj)
        print(f"n={n}: tr(S)={m1:+.1e} (=0), tr(S^2)={m2:.1f} (=n(n-1)={n*(n-1)}), "
              f"E_S={seidel_energy(adj):.4f} >= sqrt(n(n-1))={np.sqrt(n*(n-1)):.4f}")

from __future__ import annotations
import numpy as np

def turan_graph(n: int, r: int) -> np.ndarray:
    """Adjacency matrix of the Turan graph T(n, r): complete r-partite,
    parts of near-equal size, adjacent iff in different parts."""
    part = [i % r for i in range(n)]
    adj = np.zeros((n, n), dtype=int)
    for i in range(n):
        for j in range(i + 1, n):
            if part[i] != part[j]:
                adj[i, j] = adj[j, i] = 1
    return adj

def seidel_energy(adjacency: np.ndarray) -> float:
    n = adjacency.shape[0]
    s = np.ones((n, n)) - np.eye(n) - 2.0 * adjacency.astype(float)
    return float(np.sum(np.abs(np.linalg.eigvalsh(s))))

def edge_deletion_report(n: int, r: int) -> None:
    """Delete every edge of T(n, r) in turn and report the energy change."""
    adj = turan_graph(n, r)
    base = seidel_energy(adj)
    gaps = []
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i, j] == 1:
                d = adj.copy(); d[i, j] = d[j, i] = 0
                gaps.append(seidel_energy(d) - base)
    gaps = np.array(gaps)
    print(f"T({n},{r}): E_S={base:.4f}  edges={len(gaps)}  "
          f"strictly_increased={int(np.sum(gaps > 1e-9))}  min_gap={gaps.min():+.4f}")

if __name__ == "__main__":
    for n, r in ((16, 4), (20, 4), (24, 4), (20, 5)):
        edge_deletion_report(n, r)  # all satisfy n >= 4r

