function SPECTRAL-MOMENTS(A):
    n <- number of rows of A
    S <- J - I - 2A
    first  <- sum_i S[i][i]            # = 0, diagonal is zero
    second <- sum_{i,j} S[i][j]^2      # = tr(S^2) = n(n-1)
    return (first, second)
